const flow=(title,labels,foot='')=>{const pts={},polys=[],segs=[],notes=[];labels.forEach((s,i)=>{const x=i*6;Object.assign(pts,{['A'+i]:[x,0],['B'+i]:[x+5,0],['C'+i]:[x+5,2],['D'+i]:[x,2]});polys.push({v:`A${i}B${i}C${i}D${i}`,col:i%4});notes.push({at:[x+2.5,1],text:s});if(i){pts['E'+i]=[x-1,1];pts['F'+i]=[x,1];segs.push({v:'E'+i+'F'+i,arrows:1,col:0});}});if(foot)notes.push({at:[(labels.length*6-1)/2,-1.6],text:foot});return fig(title,{pts,polys,segs,notes,dots:'',hide:Object.keys(pts).join(''),view:[-1,labels.length*6,-3,4]});};
